const ArgumentType = require("../../extension-support/argument-type");
const BlockType = require("../../extension-support/block-type");
const Cast = require("../../util/cast");
const blockIconURI =
    "data:image/png;base64,";

const SpeechRecognition = webkitSpeechRecognition || SpeechRecognition;

/**
 * URL to get this extension as a module.
 * When it was loaded as a module, 'extensionURL' will be replaced a URL which is retrieved from.
 * @type {string}
 */

class Scratch3Speech2Scratch {
    /**
     * @return {string} - the name of this extension.
     */
    get EXTENSION_NAME() {
        return "Speech";
    }

    /**
     * @return {string} - the ID of this extension.
     */
    get EXTENSION_ID() {
        return "speech";
    }

    /**
     * Set URL to get this extension.
     * extensionURL will be reset when the module is loaded from the web.
     * @param {string} url - URL
     */
    static set extensionURL(url) {
        extensionURL = url;
    }

    constructor(runtime) {
        this.runtime = runtime;
        this.speech = "";
    }

    getInfo() {
        return [
            {
                id: "SpeechToText",
                name: "speech",
                extensionURL: Scratch3Speech2Scratch.extensionURL,
                blockIconURI: blockIconURI,
                blocks: [
                    {
                        opcode: "startRecognition",
                        blockType: BlockType.COMMAND,
                        text: "Voice recognition start [LANGUAGE]",
                        arguments: {
                            LANGUAGE: {
                                type: ArgumentType.STRING,
                                menu: "languageMenu",
                                defaultValue: "1",
                            },
                        },
                    },
                    {
                        opcode: "getSpeech",
                        blockType: BlockType.REPORTER,
                        text: "audio",
                    },
                ],
                menus: {
                    languageMenu: {
                        acceptReporters: true,
                        items: this.getLanguage(),
                    },
                },
            },
        ];
    }
    getLanguage() {
        return [
            {
                text: "English",
                value: "1",
            },
            {
                text: "Indonesia",
                value: "2",
            },
        ];
    }

    startRecognition(args) {
        let state = args.LANGUAGE;
        let lang = "";
        if (state == 1) {
            lang = "en-US";
        } else if (state == 2) {
            lang = "id-ID";
        }
        const recognition = new SpeechRecognition();
        recognition.lang = lang;
        recognition.interimResults = true;
        recognition.onresult = (event) => {
            this.speech = event.results[0][0].transcript;
        };
        this.speech = "";
        recognition.start();
    }

    getSpeech() {
        return this.speech;
    }
}

exports.blockClass = Scratch3Speech2Scratch; // loadable-extension needs this line.
module.exports = Scratch3Speech2Scratch;
