const ArgumentType = require("../../extension-support/argument-type");
const BlockType = require("../../extension-support/block-type");
const Cast = require("../../util/cast");
const formatMessage = require("format-message");
const ml5 = require("ml5");

const blockIconURI =
    "data:image/png;base64,";

const Message = {
    getX: {
        en: "x of [LANDMARK]",
    },
    getY: {
        en: "y of [LANDMARK]",
    },
    getZ: {
        en: "z of [LANDMARK]",
    },
    videoToggle: {
        en: "turn video [VIDEO_STATE]",
    },
    setRatio: {
        en: "set ratio to [RATIO]",
    },
    setInterval: {
        en: "Label once every [INTERVAL] seconds",
    },
    on: {
        en: "on",
    },
    off: {
        en: "off",
    },
    video_on_flipped: {
        en: "on flipped",
    },
    please_wait: {
        en: "Setup takes a while. The browser will get stuck, but please wait.",
    },
};

class Scratch3Handpose2ScratchBlocks {
    get VIDEO_MENU() {
        return [
            {
                text: Message.off[this._locale],
                value: "off",
            },
            {
                text: Message.on[this._locale],
                value: "on",
            },
            {
                text: Message.video_on_flipped[this._locale],
                value: "on-flipped",
            },
        ];
    }

    get INTERVAL_MENU() {
        return [
            {
                text: "0.1",
                value: "0.1",
            },
            {
                text: "0.2",
                value: "0.2",
            },
            {
                text: "0.5",
                value: "0.5",
            },
            {
                text: "1.0",
                value: "1.0",
            },
        ];
    }

    get RATIO_MENU() {
        return [
            {
                text: "0.5",
                value: "0.5",
            },
            {
                text: "0.75",
                value: "0.75",
            },
            {
                text: "1",
                value: "1",
            },
            {
                text: "1.5",
                value: "1.5",
            },
            {
                text: "2.0",
                value: "2.0",
            },
        ];
    }

    constructor(runtime) {
        this.runtime = runtime;

        this.landmarks = [];
        this.ratio = 0.75;
        this._locale = "en";
        this._handposeWanted = false;
        this._handpose = null;
    }

    get EXTENSION_ID() {
        return "handpose2scratch";
    }
    getInfo() {
        return [
            {
                id: "handpose2scratch",
                name: "Handpose2Scratch",
                blockIconURI: blockIconURI,
                blocks: [
                    {
                        opcode: "getX",
                        blockType: BlockType.REPORTER,
                        text: Message.getX[this._locale],
                        arguments: {
                            LANDMARK: {
                                type: ArgumentType.STRING,
                                menu: "landmark",
                                defaultValue: "1",
                            },
                        },
                    },
                    {
                        opcode: "getY",
                        blockType: BlockType.REPORTER,
                        text: Message.getY[this._locale],
                        arguments: {
                            LANDMARK: {
                                type: ArgumentType.STRING,
                                menu: "landmark",
                                defaultValue: "1",
                            },
                        },
                    },
                    {
                        opcode: "getZ",
                        blockType: BlockType.REPORTER,
                        text: Message.getZ[this._locale],
                        arguments: {
                            LANDMARK: {
                                type: ArgumentType.STRING,
                                menu: "landmark",
                                defaultValue: "1",
                            },
                        },
                    },
                    {
                        opcode: "videoToggle",
                        blockType: BlockType.COMMAND,
                        text: Message.videoToggle[this._locale],
                        arguments: {
                            VIDEO_STATE: {
                                type: ArgumentType.STRING,
                                menu: "videoMenu",
                                defaultValue: "off",
                            },
                        },
                    },
                    {
                        opcode: "setVideoTransparency",
                        text: formatMessage({
                            id: "videoSensing.setVideoTransparency",
                            default: "set video transparency to [TRANSPARENCY]",
                            description:
                                "Controls transparency of the video preview layer",
                        }),
                        arguments: {
                            TRANSPARENCY: {
                                type: ArgumentType.NUMBER,
                                defaultValue: 50,
                            },
                        },
                    },
                    {
                        opcode: "setRatio",
                        blockType: BlockType.COMMAND,
                        text: Message.setRatio[this._locale],
                        arguments: {
                            RATIO: {
                                type: ArgumentType.STRING,
                                menu: "ratioMenu",
                                defaultValue: "0.75",
                            },
                        },
                    },
                ],
                menus: {
                    landmark: [
                        {
                            text: "wrist",
                            value: "0",
                        },
                        {
                            text: "the base of thumb",
                            value: "1",
                        },
                        {
                            text: "the 2nd joint of thumb",
                            value: "2",
                        },
                        {
                            text: "the 1st joint of thumb",
                            value: "3",
                        },
                        {
                            text: "thumb",
                            value: "4",
                        },
                        {
                            text: "the 3rd joint of index finger",
                            value: "5",
                        },
                        {
                            text: "the 2nd joint of index finger",
                            value: "6",
                        },
                        {
                            text: "the 1st joint of index finger",
                            value: "7",
                        },
                        {
                            text: "index finger",
                            value: "8",
                        },
                        {
                            text: "the 3rd joint of middle finger",
                            value: "9",
                        },
                        {
                            text: "the 2nd joint of middle finger",
                            value: "10",
                        },
                        {
                            text: "the 1st joint of middle finger",
                            value: "11",
                        },
                        {
                            text: "middle finger",
                            value: "12",
                        },
                        {
                            text: "the 3rd joint of ring finger",
                            value: "13",
                        },
                        {
                            text: "the 2nd joint of ring finger",
                            value: "14",
                        },
                        {
                            text: "the 1st joint of ring finger",
                            value: "15",
                        },
                        {
                            text: "ring finger",
                            value: "16",
                        },
                        {
                            text: "the 3rd joint of little finger",
                            value: "17",
                        },
                        {
                            text: "the 2nd joint of little finger",
                            value: "18",
                        },
                        {
                            text: "the 1st joint of little finger",
                            value: "19",
                        },
                        {
                            text: "little finger",
                            value: "20",
                        },
                    ],

                    videoMenu: {
                        acceptReporters: true,
                        items: this.VIDEO_MENU,
                    },
                    ratioMenu: {
                        acceptReporters: true,
                        items: this.RATIO_MENU,
                    },
                    intervalMenu: {
                        acceptReporters: true,
                        items: this.INTERVAL_MENU,
                    },
                },
            },
        ];
    }

    getX(args) {
        let landmark = parseInt(args.LANDMARK, 10) - 1;
        if (this.landmarks[landmark]) {
            if (this.runtime.ioDevices.video.mirror === false) {
                return -1 * (240 - this.landmarks[landmark][0] * this.ratio);
            } else {
                return 240 - this.landmarks[landmark][0] * this.ratio;
            }
        } else {
            return "";
        }
    }

    getY(args) {
        let landmark = parseInt(args.LANDMARK, 10) - 1;
        if (this.landmarks[landmark]) {
            return 180 - this.landmarks[landmark][1] * this.ratio;
        } else {
            return "";
        }
    }

    getZ(args) {
        let landmark = parseInt(args.LANDMARK, 10) - 1;
        if (this.landmarks[landmark]) {
            return this.landmarks[landmark][2];
        } else {
            return "";
        }
    }

    async videoToggle(args) {
        const state = args.VIDEO_STATE;
        if (state === "off") {
            this._handposeWanted = false;
            this._handpose = null;
            this.runtime.ioDevices.video.disableVideo();
        } else {
            this._handposeWanted = true;
            this.runtime.ioDevices.video.mirror = state === "on";
            try {
                await this.runtime.ioDevices.video.enableVideo();
            } catch (e) {
                if (this._handposeWanted) {
                    console.warn("Handpose: enableVideo failed", e);
                }
                return;
            }
            if (!this._handposeWanted) return;
            this._startHandpose();
        }
    }

    _startHandpose() {
        const videoDev = this.runtime.ioDevices.video;
        if (!videoDev || !videoDev.provider) {
            console.warn("Handpose: video device not available");
            return;
        }
        this.video = videoDev.provider.video;
        if (!this.video) {
            console.warn("Handpose: video element null after enableVideo resolved", videoDev.provider);
            return;
        }

        alert(Message.please_wait[this._locale]);

        this._handpose = ml5.handpose(this.video, () => {
            console.log("Model loaded!");
        });

        this._handpose.on("predict", (hands) => {
            hands.forEach((hand) => {
                this.landmarks = hand.landmarks;
            });
        });
    }

    /**
     * A scratch command block handle that configures the video preview's
     * transparency from passed arguments.
     * @param {object} args - the block arguments
     * @param {number} args.TRANSPARENCY - the transparency to set the video
     *   preview to
     */
    setVideoTransparency(args) {
        const transparency = Cast.toNumber(args.TRANSPARENCY);
        this.globalVideoTransparency = transparency;
        this.runtime.ioDevices.video.setPreviewGhost(transparency);
    }

    setRatio(args) {
        this.ratio = parseFloat(args.RATIO);
    }
}

module.exports = Scratch3Handpose2ScratchBlocks;
