import classNames from "classnames";
import omit from "lodash.omit";
import PropTypes from "prop-types";
import React from "react";
import {
    defineMessages,
    FormattedMessage,
    injectIntl,
    intlShape,
} from "react-intl";
import { connect } from "react-redux";
import MediaQuery from "react-responsive";
import { Tab, Tabs, TabList, TabPanel } from "react-tabs";
import tabStyles from "react-tabs/style/react-tabs.css";
import VM from "openblock-vm";
import Renderer from "scratch-render";

import Blocks from "../../containers/blocks.jsx";
import CostumeTab from "../../containers/costume-tab.jsx";
import TargetPane from "../../containers/target-pane.jsx";
import SoundTab from "../../containers/sound-tab.jsx";
import StageWrapper from "../../containers/stage-wrapper.jsx";
import Loader from "../loader/loader.jsx";
import LandingPage from "../landing-page/landing-page.jsx";
import Box from "../box/box.jsx";
import MenuBar from "../menu-bar/menu-bar.jsx";
import CostumeLibrary from "../../containers/costume-library.jsx";
import BackdropLibrary from "../../containers/backdrop-library.jsx";
import Watermark from "../../containers/watermark.jsx";
import Hardware from "../../containers/hardware.jsx";
import HardwareHeader from "../../containers/hardware-header.jsx";
import PythonIde from "../../containers/python-ide.jsx";

// eslint-disable-next-line no-unused-vars
import Backpack from "../../containers/backpack.jsx";
import WebGlModal from "../../containers/webgl-modal.jsx";
import TipsLibrary from "../../containers/tips-library.jsx";
import Cards from "../../containers/cards.jsx";
import Alerts from "../../containers/alerts.jsx";
import DragLayer from "../../containers/drag-layer.jsx";
import ConnectionModal from "../../containers/connection-modal.jsx";
import ExtensionConnectionModal from "../../containers/extension-connection-modal.jsx";
import UploadProgress from "../../containers/upload-progress.jsx";
import Onboarding from "../../containers/onboarding.jsx";
import Modal from "../modal/modal.jsx";
import TelemetryModal from "../telemetry-modal/telemetry-modal.jsx";
import UpdateModal from "../../containers/update-modal.jsx";

import layout, { STAGE_SIZE_MODES } from "../../lib/layout-constants";
import { resolveStageSize } from "../../lib/screen-utils";
import { nomokitMlIndexUrl } from "../../lib/nomokit-ml-url";
import { nomokitCppIndexUrl } from "../../lib/nomokit-cpp-url";

import styles from "./gui.css";
import addExtensionIcon from "./icon--extensions.svg";
import codeIcon from "./icon--code.svg";
import pythonIcon from "./python-logo.svg";
import costumesIcon from "./icon--costumes.svg";
import soundsIcon from "./icon--sounds.svg";

const messages = defineMessages({
    addExtension: {
        id: "gui.gui.addExtension",
        description: "Button to add an extension in the target pane",
        defaultMessage: "Add Extension",
    },
});

// Cache this value to only retrieve it once the first time.
// Assume that it doesn't change for a session.
let isRendererSupported = null;

const GUIComponent = (props) => {
    const {
        accountNavOpen,
        activeTabIndex,
        alertsVisible,
        authorId,
        authorThumbnailUrl,
        authorUsername,
        basePath,
        backdropLibraryVisible,
        // eslint-disable-next-line no-unused-vars
        backpackHost,
        // eslint-disable-next-line no-unused-vars
        backpackVisible,
        blocksTabVisible,
        cardsVisible,
        canChangeLanguage,
        canCreateNew,
        canEditTitle,
        canManageFiles,
        canRemix,
        canSave,
        canCreateCopy,
        canShare,
        canUseCloud,
        children,
        showLandingPage,
        showJuniorContent,
        showMLContent,
        showCppContent,
        onSelectJuniorCode,
        onSelectBlockCode,
        onSelectPythonIDE,
        onSelectML,
        onSelectCpp,
        onCloseJuniorContent,
        onCloseMLContent,
        onCloseCppContent,
        onMLHostRef,
        onShowLandingPage,
        connectionModalVisible,
        extensionConnectionModalVisible,
        uploadProgressVisible,
        onboardingVisible,
        costumeLibraryVisible,
        costumesTabVisible,
        updateModalVisible,
        enableCommunity,
        intl,
        isCreating,
        isFullScreen,
        isPlayerOnly,
        isRtl,
        isShared,
        isTelemetryEnabled,
        loading,
        logo,
        renderLogin,
        onClickAbout,
        onClickAccountNav,
        onCloseAccountNav,
        onLogOut,
        onOpenRegistration,
        onToggleLoginOpen,
        onAbortUpdate,
        onActivateCostumesTab,
        onActivateSoundsTab,
        onActivateTab,
        onClickLogo,
        onClickCheckUpdate,
        onClickUpdate,
        onClickClearCache,
        onClickInstallDriver,
        onExtensionButtonClick,
        onProjectTelemetryEvent,
        onRequestCloseBackdropLibrary,
        onRequestCloseCostumeLibrary,
        onRequestCloseTelemetryModal,
        onSeeCommunity,
        onShare,
        onShowPrivacyPolicy,
        onStartSelectingFileUpload,
        onShowMessageBox,
        onTelemetryModalCancel,
        onTelemetryModalOptIn,
        onTelemetryModalOptOut,
        showComingSoon,
        soundsTabVisible,
        pythonTabVisible,
        stageSizeMode,
        targetIsStage,
        telemetryModalVisible,
        tipsLibraryVisible,
        vm,
        isRealtimeMode,
        realtimeConnection,
        showSwitchModeDialog,
        switchFromMode,
        switchToMode,
        onConfirmSwitchMode,
        onCancelSwitchMode,
        inputMode,
        ...componentProps
    } = omit(props, "dispatch");
    if (children) {
        return <Box {...componentProps}>{children}</Box>;
    }

    const tabClassNames = {
        tabs: styles.tabs,
        tab: classNames(tabStyles.reactTabsTab, styles.tab),
        tabList: classNames(tabStyles.reactTabsTabList, styles.tabList),
        tabPanel: classNames(tabStyles.reactTabsTabPanel, styles.tabPanel),
        tabPanelSelected: classNames(
            tabStyles.reactTabsTabPanelSelected,
            styles.isSelected,
        ),
        tabSelected: classNames(
            tabStyles.reactTabsTabSelected,
            styles.isSelected,
        ),
    };

    if (isRendererSupported === null) {
        isRendererSupported = Renderer.isSupported();
    }

    const switchFromLabel = switchFromMode === "python" ? "Python" : "Block";
    const switchToLabel = switchToMode === "python" ? "Python" : "Block";

    return (
        <React.Fragment>
            {showLandingPage ? (
                <LandingPage
                    onSelectJuniorCode={onSelectJuniorCode}
                    onSelectBlockCode={onSelectBlockCode}
                    onSelectPythonIDE={onSelectPythonIDE}
                    onSelectML={onSelectML}
                    onSelectCpp={onSelectCpp}
                />
            ) : null}
            <MediaQuery minWidth={layout.fullSizeMinWidth}>
                {(isFullSize) => {
                    const stageSize = resolveStageSize(
                        stageSizeMode,
                        isFullSize,
                    );

                    return isPlayerOnly ? (
                        <StageWrapper
                            isFullScreen={isFullScreen}
                            isRendererSupported={isRendererSupported}
                            isRtl={isRtl}
                            loading={loading}
                            stageSize={STAGE_SIZE_MODES.large}
                            vm={vm}
                        >
                            {alertsVisible ? (
                                <Alerts
                                    vm={vm}
                                    className={styles.alertsContainer}
                                />
                            ) : null}
                        </StageWrapper>
                    ) : (
                        <Box
                            className={styles.pageWrapper}
                            dir={isRtl ? "rtl" : "ltr"}
                            {...componentProps}
                        >
                            {telemetryModalVisible ? (
                                <TelemetryModal
                                    isRtl={isRtl}
                                    isTelemetryEnabled={isTelemetryEnabled}
                                    onCancel={onTelemetryModalCancel}
                                    onOptIn={onTelemetryModalOptIn}
                                    onOptOut={onTelemetryModalOptOut}
                                    onRequestClose={
                                        onRequestCloseTelemetryModal
                                    }
                                    onShowPrivacyPolicy={onShowPrivacyPolicy}
                                />
                            ) : null}
                            {loading ? <Loader /> : null}
                            {isCreating ? (
                                <Loader messageId="gui.loader.creating" />
                            ) : null}
                            {isRendererSupported ? null : (
                                <WebGlModal isRtl={isRtl} />
                            )}
                            {tipsLibraryVisible ? <TipsLibrary /> : null}
                            {cardsVisible ? <Cards /> : null}
                            {onboardingVisible ? <Onboarding /> : null}
                            {showSwitchModeDialog ? (
                                <Modal
                                    className={styles.switchModeModal}
                                    contentLabel="Switching Coding Environment!"
                                    onRequestClose={onCancelSwitchMode}
                                >
                                    <Box className={styles.switchModeBody}>
                                        <Box
                                            className={
                                                styles.switchModeVisualRow
                                            }
                                        >
                                            <Box
                                                className={
                                                    styles.switchModeChip
                                                }
                                            >
                                                {switchFromLabel}
                                            </Box>
                                            <Box
                                                className={
                                                    styles.switchModeArrow
                                                }
                                            >
                                                {">>"}
                                            </Box>
                                            <Box
                                                className={
                                                    styles.switchModeChip
                                                }
                                            >
                                                {switchToLabel}
                                            </Box>
                                        </Box>
                                        <Box className={styles.switchModeText}>
                                            You are switching to the{" "}
                                            {switchToLabel} coding environment.
                                            Python code and block code do not
                                            run in parallel.
                                        </Box>
                                        <Box
                                            className={styles.switchModeActions}
                                        >
                                            <button
                                                className={
                                                    styles.switchModePrimaryButton
                                                }
                                                onClick={onConfirmSwitchMode}
                                                type="button"
                                            >
                                                Go Ahead
                                            </button>
                                            <button
                                                className={
                                                    styles.switchModeSecondaryButton
                                                }
                                                onClick={onCancelSwitchMode}
                                                type="button"
                                            >
                                                Cancel
                                            </button>
                                        </Box>
                                    </Box>
                                </Modal>
                            ) : null}
                            {alertsVisible ? (
                                <Alerts
                                    vm={vm}
                                    className={styles.alertsContainer}
                                />
                            ) : null}
                            {connectionModalVisible ? (
                                <ConnectionModal vm={vm} />
                            ) : null}
                            {extensionConnectionModalVisible ? (
                                <ExtensionConnectionModal vm={vm} />
                            ) : null}
                            {uploadProgressVisible ? (
                                <UploadProgress vm={vm} />
                            ) : null}
                            {costumeLibraryVisible ? (
                                <CostumeLibrary
                                    vm={vm}
                                    onRequestClose={
                                        onRequestCloseCostumeLibrary
                                    }
                                />
                            ) : null}
                            {backdropLibraryVisible ? (
                                <BackdropLibrary
                                    vm={vm}
                                    onRequestClose={
                                        onRequestCloseBackdropLibrary
                                    }
                                />
                            ) : null}
                            {updateModalVisible ? (
                                <UpdateModal
                                    vm={vm}
                                    onAbortUpdate={onAbortUpdate}
                                    onClickUpdate={onClickUpdate}
                                    onShowMessageBox={onShowMessageBox}
                                />
                            ) : null}
                            <MenuBar
                                accountNavOpen={accountNavOpen}
                                authorId={authorId}
                                authorThumbnailUrl={authorThumbnailUrl}
                                authorUsername={authorUsername}
                                canChangeLanguage={canChangeLanguage}
                                canCreateCopy={canCreateCopy}
                                canCreateNew={canCreateNew}
                                canEditTitle={canEditTitle}
                                canManageFiles={canManageFiles}
                                canRemix={canRemix}
                                canSave={canSave}
                                canShare={canShare}
                                className={styles.menuBarPosition}
                                enableCommunity={enableCommunity}
                                isShared={isShared}
                                logo={logo}
                                renderLogin={renderLogin}
                                showComingSoon={showComingSoon}
                                onClickAbout={onClickAbout}
                                onClickAccountNav={onClickAccountNav}
                                onClickLogo={onClickLogo}
                                onCloseAccountNav={onCloseAccountNav}
                                onLogOut={onLogOut}
                                onOpenRegistration={onOpenRegistration}
                                onProjectTelemetryEvent={
                                    onProjectTelemetryEvent
                                }
                                onSeeCommunity={onSeeCommunity}
                                onShare={onShare}
                                onStartSelectingFileUpload={
                                    onStartSelectingFileUpload
                                }
                                onShowMessageBox={onShowMessageBox}
                                onToggleLoginOpen={onToggleLoginOpen}
                                onClickCheckUpdate={onClickCheckUpdate}
                                onClickClearCache={onClickClearCache}
                                onClickInstallDriver={onClickInstallDriver}
                                onShowLandingPage={onShowLandingPage}
                            />
                            <Box className={styles.bodyWrapper}>
                                <Box className={styles.flexWrapper}>
                                    <Box
                                        className={classNames(
                                            styles.editorWrapper,
                                            inputMode === "python" &&
                                                styles.pythonEditorWrapper,
                                        )}
                                    >
                                        <Tabs
                                            forceRenderTabPanel
                                            className={tabClassNames.tabs}
                                            selectedIndex={activeTabIndex}
                                            selectedTabClassName={
                                                tabClassNames.tabSelected
                                            }
                                            selectedTabPanelClassName={
                                                tabClassNames.tabPanelSelected
                                            }
                                            onSelect={onActivateTab}
                                        >
                                            <TabList
                                                className={
                                                    tabClassNames.tabList
                                                }
                                            >
                                                <Tab
                                                    className={
                                                        tabClassNames.tab
                                                    }
                                                >
                                                    <img
                                                        draggable={false}
                                                        src={codeIcon}
                                                    />
                                                    <FormattedMessage
                                                        defaultMessage="Code"
                                                        description="Button to get to the code panel"
                                                        id="gui.gui.codeTab"
                                                    />
                                                </Tab>
                                                <Tab
                                                    className={classNames(
                                                        tabClassNames.tab,
                                                        isRealtimeMode ||
                                                            inputMode ===
                                                                "python"
                                                            ? styles.hideCustomAndSoundTab
                                                            : styles.showCustomAndSoundTab,
                                                    )}
                                                    onClick={
                                                        onActivateCostumesTab
                                                    }
                                                >
                                                    <img
                                                        draggable={false}
                                                        src={costumesIcon}
                                                    />
                                                    {targetIsStage ? (
                                                        <FormattedMessage
                                                            defaultMessage="Backdrops"
                                                            description="Button to get to the backdrops panel"
                                                            id="gui.gui.backdropsTab"
                                                        />
                                                    ) : (
                                                        <FormattedMessage
                                                            defaultMessage="Costumes"
                                                            description="Button to get to the costumes panel"
                                                            id="gui.gui.costumesTab"
                                                        />
                                                    )}
                                                </Tab>
                                                <Tab
                                                    className={classNames(
                                                        tabClassNames.tab,
                                                        isRealtimeMode ||
                                                            inputMode ===
                                                                "python"
                                                            ? styles.hideCustomAndSoundTab
                                                            : styles.showCustomAndSoundTab,
                                                    )}
                                                    onClick={
                                                        onActivateSoundsTab
                                                    }
                                                >
                                                    <img
                                                        draggable={false}
                                                        src={soundsIcon}
                                                    />
                                                    <FormattedMessage
                                                        defaultMessage="Sounds"
                                                        description="Button to get to the sounds panel"
                                                        id="gui.gui.soundsTab"
                                                    />
                                                </Tab>
                                                <Tab
                                                    className={classNames(
                                                        tabClassNames.tab,
                                                        !isRealtimeMode
                                                            ? styles.hidePythonTab
                                                            : null,
                                                    )}
                                                >
                                                    <img
                                                        draggable={false}
                                                        src={pythonIcon}
                                                    />
                                                    <FormattedMessage
                                                        defaultMessage="Python"
                                                        description="Button to get to the Python IDE panel"
                                                        id="gui.gui.pythonTab"
                                                    />
                                                </Tab>
                                            </TabList>
                                            <TabPanel
                                                className={
                                                    tabClassNames.tabPanel
                                                }
                                            >
                                                <Box
                                                    className={
                                                        styles.blocksWrapper
                                                    }
                                                >
                                                    <Blocks
                                                        canUseCloud={
                                                            canUseCloud
                                                        }
                                                        grow={1}
                                                        isVisible={
                                                            blocksTabVisible
                                                        }
                                                        options={{
                                                            media: `${basePath}static/blocks-media/`,
                                                        }}
                                                        stageSize={stageSize}
                                                        vm={vm}
                                                        onShowMessageBox={
                                                            onShowMessageBox
                                                        }
                                                    />
                                                </Box>
                                                <Box
                                                    className={
                                                        styles.extensionButtonContainer
                                                    }
                                                >
                                                    <button
                                                        className={
                                                            styles.extensionButton
                                                        }
                                                        title={intl.formatMessage(
                                                            messages.addExtension,
                                                        )}
                                                        onClick={
                                                            onExtensionButtonClick
                                                        }
                                                    >
                                                        <img
                                                            className={
                                                                styles.extensionButtonIcon
                                                            }
                                                            draggable={false}
                                                            src={
                                                                addExtensionIcon
                                                            }
                                                        />
                                                    </button>
                                                </Box>
                                                <Box
                                                    className={styles.watermark}
                                                >
                                                    <Watermark />
                                                </Box>
                                            </TabPanel>
                                            <TabPanel
                                                className={
                                                    tabClassNames.tabPanel
                                                }
                                            >
                                                {costumesTabVisible ? (
                                                    <CostumeTab vm={vm} />
                                                ) : null}
                                            </TabPanel>
                                            <TabPanel
                                                className={
                                                    tabClassNames.tabPanel
                                                }
                                            >
                                                {soundsTabVisible ? (
                                                    <SoundTab
                                                        vm={vm}
                                                        onShowMessageBox={
                                                            onShowMessageBox
                                                        }
                                                    />
                                                ) : null}
                                            </TabPanel>
                                            <TabPanel
                                                className={
                                                    tabClassNames.tabPanel
                                                }
                                            >
                                                {pythonTabVisible ? (
                                                    <PythonIde />
                                                ) : null}
                                            </TabPanel>
                                        </Tabs>
                                        {/*
                                    backpackVisible ? (
                                        <Backpack host={backpackHost} />
                                    ) : null
                                */}
                                    </Box>
                                    <Box
                                        className={classNames(
                                            styles.stageAndTargetWrapper,
                                            styles[stageSize],
                                            isRealtimeMode
                                                ? styles.showStage
                                                : styles.hideStage,
                                        )}
                                    >
                                        <StageWrapper
                                            isFullScreen={isFullScreen}
                                            isRendererSupported={
                                                isRendererSupported
                                            }
                                            isRtl={isRtl}
                                            stageSize={stageSize}
                                            vm={vm}
                                        />
                                        <Box className={styles.targetWrapper}>
                                            <TargetPane
                                                stageSize={stageSize}
                                                vm={vm}
                                            />
                                        </Box>
                                    </Box>
                                    {isRealtimeMode === false ? (
                                        <HardwareHeader vm={vm} />
                                    ) : null}
                                    {isRealtimeMode === false &&
                                    stageSizeMode !== STAGE_SIZE_MODES.hide ? (
                                        <Hardware vm={vm} />
                                    ) : null}
                                </Box>
                                <DragLayer />
                            </Box>
                        </Box>
                    );
                }}
            </MediaQuery>
            {showJuniorContent ? (
                <Box className={styles.juniorOverlay}>
                    <iframe
                        className={styles.juniorIframe}
                        src={
                            window.electronAPI?.getAppPath
                                ? `file:///${window.electronAPI.getAppPath().replace(/\\/g, "/")}/nomokitjr/index.html`
                                : "/nomokitjr/index.html"
                        }
                        title="Nomokit Jr"
                    />
                </Box>
            ) : null}
            {/*
              * Mounted unconditionally, and only *repositioned* when the overlay closes. This one
              * iframe is both the ML trainer the student sees and the inference runtime the
              * NomoKit ML blocks talk to, so unmounting it on close would drop the MessagePort and
              * tear down any loaded model mid-project.
              *
              * Offscreen rather than display:none -- a display:none iframe gets no
              * requestAnimationFrame, and speech-commands' feature extractor schedules its polling
              * loop that way, so audio classification would silently stall. visibility:hidden is
              * unreliable across Chromium versions for the same reason.
              */}
            <Box className={showMLContent ? styles.juniorOverlay : styles.mlHostHidden}>
                {showMLContent ? (
                    <button
                        className={styles.juniorCloseButton}
                        onClick={onCloseMLContent}
                    >
                        &times;
                    </button>
                ) : null}
                <iframe
                    allow="camera; microphone"
                    className={styles.juniorIframe}
                    ref={onMLHostRef}
                    referrerPolicy="no-referrer"
                    src={nomokitMlIndexUrl()}
                    title="NomoML"
                />
            </Box>
            {showCppContent ? (
                <Box className={styles.juniorOverlay}>
                    <iframe
                        className={styles.juniorIframe}
                        src={nomokitCppIndexUrl()}
                        title="Nomo C++"
                    />
                </Box>
            ) : null}
        </React.Fragment>
    );
};

GUIComponent.propTypes = {
    accountNavOpen: PropTypes.bool,
    activeTabIndex: PropTypes.number,
    authorId: PropTypes.oneOfType([PropTypes.string, PropTypes.bool]), // can be false
    authorThumbnailUrl: PropTypes.string,
    authorUsername: PropTypes.oneOfType([PropTypes.string, PropTypes.bool]), // can be false
    backdropLibraryVisible: PropTypes.bool,
    backpackHost: PropTypes.string,
    backpackVisible: PropTypes.bool,
    basePath: PropTypes.string,
    blocksTabVisible: PropTypes.bool,
    canChangeLanguage: PropTypes.bool,
    canCreateCopy: PropTypes.bool,
    canCreateNew: PropTypes.bool,
    canEditTitle: PropTypes.bool,
    canManageFiles: PropTypes.bool,
    canRemix: PropTypes.bool,
    canSave: PropTypes.bool,
    canShare: PropTypes.bool,
    canUseCloud: PropTypes.bool,
    cardsVisible: PropTypes.bool,
    children: PropTypes.node,
    costumeLibraryVisible: PropTypes.bool,
    costumesTabVisible: PropTypes.bool,
    enableCommunity: PropTypes.bool,
    intl: intlShape.isRequired,
    isCreating: PropTypes.bool,
    isFullScreen: PropTypes.bool,
    isPlayerOnly: PropTypes.bool,
    isRtl: PropTypes.bool,
    isShared: PropTypes.bool,
    loading: PropTypes.bool,
    logo: PropTypes.string,
    onActivateCostumesTab: PropTypes.func,
    onActivateSoundsTab: PropTypes.func,
    onActivateTab: PropTypes.func,
    onClickAccountNav: PropTypes.func,
    onClickLogo: PropTypes.func,
    onClickCheckUpdate: PropTypes.func,
    onAbortUpdate: PropTypes.func,
    onClickUpdate: PropTypes.func,
    onClickClearCache: PropTypes.func,
    onClickInstallDriver: PropTypes.func,
    onCloseAccountNav: PropTypes.func,
    onExtensionButtonClick: PropTypes.func,
    onLogOut: PropTypes.func,
    onMLHostRef: PropTypes.func,
    onOpenRegistration: PropTypes.func,
    onRequestCloseBackdropLibrary: PropTypes.func,
    onRequestCloseCostumeLibrary: PropTypes.func,
    onRequestCloseTelemetryModal: PropTypes.func,
    onSeeCommunity: PropTypes.func,
    onShare: PropTypes.func,
    onShowPrivacyPolicy: PropTypes.func,
    onStartSelectingFileUpload: PropTypes.func,
    onShowMessageBox: PropTypes.func.isRequired,
    onConfirmSwitchMode: PropTypes.func,
    onCancelSwitchMode: PropTypes.func,
    onTabSelect: PropTypes.func,
    onTelemetryModalCancel: PropTypes.func,
    onTelemetryModalOptIn: PropTypes.func,
    onTelemetryModalOptOut: PropTypes.func,
    onToggleLoginOpen: PropTypes.func,
    renderLogin: PropTypes.func,
    showComingSoon: PropTypes.bool,
    soundsTabVisible: PropTypes.bool,
    pythonTabVisible: PropTypes.bool,
    inputMode: PropTypes.string,
    stageSizeMode: PropTypes.oneOf(Object.keys(STAGE_SIZE_MODES)),
    targetIsStage: PropTypes.bool,
    telemetryModalVisible: PropTypes.bool,
    tipsLibraryVisible: PropTypes.bool,
    onboardingVisible: PropTypes.bool,
    showSwitchModeDialog: PropTypes.bool,
    switchFromMode: PropTypes.string,
    switchToMode: PropTypes.string,
    vm: PropTypes.instanceOf(VM).isRequired,
    isRealtimeMode: PropTypes.bool,
    realtimeConnection: PropTypes.bool,
};
GUIComponent.defaultProps = {
    backpackHost: null,
    backpackVisible: false,
    basePath: "./",
    canChangeLanguage: true,
    canCreateNew: false,
    canEditTitle: false,
    canManageFiles: true,
    canRemix: false,
    canSave: false,
    canCreateCopy: false,
    canShare: false,
    canUseCloud: false,
    enableCommunity: false,
    isCreating: false,
    isShared: false,
    loading: false,
    showComingSoon: false,
    stageSizeMode: STAGE_SIZE_MODES.large,
};

const mapStateToProps = (state) => ({
    // This is the button's mode, as opposed to the actual current state
    stageSizeMode: state.scratchGui.stageSize.stageSize,
});

export default injectIntl(connect(mapStateToProps)(GUIComponent));
