    setVideoTransparency(args) {
        const transparency = Cast.toNumber(args.TRANSPARENCY);
        this.globalVideoTransparency = transparency;
        this.runtime.ioDevices.video.setPreviewGhost(transparency);
    }

    showBoundingBoxes(args) {
        const state = args.SHOW_BOUNDING_BOXES;
        if (state === "show") {
            this.showBounding = true;
        } else {
            this.showBounding = false;
        }
    }

    videoToggle(args) {
        const state = args.VIDEO_STATE;
        const transparency = Cast.toNumber(args.TRANSPARENCY);

        if (state === "off") {
            this.runtime.ioDevices.video.disableVideo();
        } else {
            this.runtime.ioDevices.video.enableVideo();
            this.globalVideoTransparency = transparency;
            this.runtime.ioDevices.video.setPreviewGhost(transparency);
            this.runtime.ioDevices.video.mirror = state === "on";
        }
    }

    analyseImageFrom() {
        if (!this.objectDetector) {
            return Promise.resolve([]);
        }
        if (!this.modelReady) {
            return new Promise((resolve) => {
                const waitForModel = () => {
                    if (this.modelReady) {
                        resolve(this._doAnalyse());
                    } else {
                        setTimeout(waitForModel, 200);
                    }
                };
                waitForModel();
            });
        }
        return this._doAnalyse();
    }

    _doAnalyse() {
        const videoEl = this.runtime && this.runtime.ioDevices && this.runtime.ioDevices.video && this.runtime.ioDevices.video.provider && this.runtime.ioDevices.video.provider.video;
        if (!videoEl || !this.canvas || !this.ctx) {
            return Promise.resolve([]);
        }
        if (this.firstLayer) {
            this.canvas.width = this.firstLayer.width;
            this.canvas.height = this.firstLayer.height;
        }
        // Draw current video frame to overlay canvas so ml5 can read it
        this.ctx.drawImage(videoEl, 0, 0, this.canvas.width, this.canvas.height);
        return new Promise((resolve) => {
            this.objectDetector.detect(this.canvas, (error, results) => {
                if (error) {
                    console.error(error);
                    resolve([]);
                    return;
                }
                this.objects = results;
                this.draw();
                resolve(["Done"]);
            });
        });
    }

    draw() {
        if (!this.ctx) return;
        if (this.showBounding) {
            this.ctx.fillStyle = "rgba(0, 0, 0, 0)";
            this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
            this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

            for (let i = 0; i < this.objects.length; i++) {
                if (this.objects[i].confidence < this.confidenceThreshold) {
                    continue;
                }

                this.ctx.font = "16px Arial";
                this.ctx.fillStyle = "red";
                this.ctx.fillText(
                    this.objects[i].label +
                        " " +
                        this.objects[i].confidence.toFixed(2),
                    this.objects[i].x + 4,
                    this.objects[i].y + 16
                );

                this.ctx.beginPath();
                this.ctx.rect(
                    this.objects[i].x,
                    this.objects[i].y,
                    this.objects[i].width,
                    this.objects[i].height
                );
                this.ctx.strokeStyle = "red";
                this.ctx.lineWidth = 2;
                this.ctx.stroke();
                this.ctx.closePath();
            }
        }
    }

    getCounts() {
        if (this.objects) {
            return this.objects.length;
        }
        return 0;
    }

    isDetected(args) {
        const label = args.LABEL;
        if (this.objects) {
            for (let i = 0; i < this.objects.length; i++) {
                if (this.objects[i].label === label) {
                    return true;
                }
            }
        }
        return false;
    }

    getCountOf(args) {
        const label = args.LABEL;
        let count = 0;
        if (this.objects) {
            for (let i = 0; i < this.objects.length; i++) {
                if (this.objects[i].label === label) {
                    count++;
                }
            }
        }
        return count;
    }
    setDetectionThreshold(args) {
        let threshold = Cast.toNumber(args.DETECTION_THRESHOLD);
        threshold = MathUtil.clamp(threshold, 0, 1);
        this.confidenceThreshold = threshold;
    }

    getObjects(args) {
        let objects = this.objects[args.INDEX];

        if (!objects) {
            return "No object detected";
        }
        if (args.PROPERTY === "label") {
            return objects.label;
        }
        if (args.PROPERTY === "confidence") {
            return objects.confidence;
        }
        if (args.PROPERTY === "positionX") {
            return objects.x;
        }
        if (args.PROPERTY === "positionY") {
            return objects.y;
        }
        if (args.PROPERTY === "width") {
            return objects.width;
        }
        if (args.PROPERTY === "height") {
            return objects.height;
        }
    }
